def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            stack = [(r, c)]
            while stack:
                y, x = stack.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    q = (y + dy, x + dx)
                    if (0 <= q[0] < h and 0 <= q[1] < w and q not in seen
                            and grid[q[0]][q[1]] == color):
                        seen.add(q)
                        cells.add(q)
                        stack.append(q)
            min_r = min(y for y, x in cells)
            min_c = min(x for y, x in cells)
            shape = frozenset((y - min_r, x - min_c) for y, x in cells)
            objects.append((color, cells, shape))
    out = [row[:] for row in grid]
    for color, cells, shape in objects:
        if color != 1:
            continue
        matches = [other_color for other_color, other_cells, other_shape in objects
                   if other_color != 1 and other_shape == shape]
        if matches:
            target = matches[0]
            for r, c in cells:
                out[r][c] = target
    return out
